mapper.select:
select * from( SELECT sp.id,sp.flow_id,sp.flow_no,sp.factory_id,sp.factory,sp.event_source,sp.event_id,M1.field_name event_type,sp.task_id, sp.team_id,M2.field_name team_name,case sp.event_source when 2 then '事件上报' else sp.plan_name end plan_name, sp.is_exception,sp.event_level,sp.duty_dept,sp.occur_time,sp.event_address,sp.is_keynote,sp.problem_desc, sp.problem_image,sp.plan_deal_time,sp.plan_measure,sp.is_scene,sp.is_transfer,sp.transfer_dept,sp.deal_person,sp.deal_person_group, sp.guard_person,sp.deal_time,sp.deal_record,sp.deal_image,sp.result_score,sp.result_desc,sp.result_person, sp.is_delay,sp.submit_name,sp.submit_dept,sp.grab_person,sp.grab_time,DATE_FORMAT(sp.create_time,'%Y-%m-%d %H:%i:%s') create_time, sp.is_grab,sp.is_dispatch,sp.dispatch_person,IFNULL(dh.rework_num,0) rework_num,sp.status,sp.is_deal_transfer,sp.cur_deal_handler, '' car_number,'' telephone,'' driver_name,1 plan_type,'' is_assign,sp.cur_node_id, CONCAT(#{bpmUrlPre},'&formInstanceId=',sp.id,'&processId=',sp.flow_id) flow_url , '' goods_out_flow_url FROM safety_process_patrol sp LEFT JOIN (select pd.process_id,count(1) rework_num from safety_patrol_deal_history pd group by pd.process_id) dh on sp.id = dh.process_id LEFT JOIN SAFETY.safety_field_manage M1 ON sp.event_id = M1.ID LEFT JOIN SAFETY.safety_field_manage M2 ON sp.team_id = M2.ID WHERE 1 = 1
union all SELECT sv.id,'' flow_id,sv.flow_no,sv.factory_id,sv.factory,sv.event_source,sv.event_id,M3.field_name event_type,sv.task_id, sv.team_id,M4.field_name team_name,sv.plan_name,0 is_exception,'' event_level,'' duty_dept,'' occur_time,'' event_address, 0 is_keynote,'' problem_desc,'' problem_image, '' plan_deal_time,'' plan_measure,0 is_scene,0 is_transfer, '' transfer_dept,sv.check_person deal_person,sv.check_dept deal_person_group,'' guard_person,sv.check_time deal_time,'' deal_record,'' deal_image,'' result_score,'' result_desc,'' result_person, 0 is_delay, sv.check_person submit_name,sv.check_dept submit_dept,'' grab_person,'' grab_time,DATE_FORMAT(sv.create_time,'%Y-%m-%d %H:%i:%s') create_time,0 is_grab,0 is_dispatch,'' dispatch_person,0 rework_num,'' status,0, '' cur_deal_handler, sv.car_number,sv.telephone,sv.driver_name,2 plan_type,'' is_assign,'' cur_node_id, CONCAT(#{bpmUrlPre},'&formInstanceId=',sv.id,'&processId=',sv.flow_no) flow_url , '' goods_out_flow_url FROM safety_validate_environment sv LEFT JOIN SAFETY.safety_field_manage M3 ON sv.event_id = M3.ID LEFT JOIN SAFETY.safety_field_manage M4 ON sv.team_id = M4.ID where 1 = 1
union all select ep.id, ep.process_id as flow_id, ep.flow_no as flow_no, ep.site_id as factory_id, ep.site_name as factory, '' as event_source, '' as event_id, ep.event_type , '' as task_id, '' as team_id, ep.issue_type as team_name, '出门证违规上报' as plan_name, '' as is_exception, ep.event_level , ep.responsible_person_department as duty_dept, ep.event_occurrence_time as occur_time, ep.specific_location as event_address, '' as is_keynote, ep.issue_description as problem_desc, '' problem_image, '' plan_deal_time, '' plan_measure, '' is_scene, '' is_transfer, '' transfer_dept, ep.remediation_name as deal_person, '' deal_person_group, '' guard_person, ep.remediation_completion_time as deal_time, ep.remediation_measure as deal_record, '' deal_image, '' result_score, '' result_desc, '' result_person, '' is_delay, ep.reporter_name as submit_name, '' submit_dept, '' grab_person, '' grab_time, ep.creation_time as create_time, '' is_grab, '' is_dispatch, '' dispatch_person, '' rework_num, '' status, '' is_deal_transfer, '' cur_deal_handler, '' car_number, '' telephone, '' driver_name, 1 plan_type, 0 as is_assign,'' cur_node_id, CONCAT(#{goodsExceptionBpmUrlPre},'&formInstanceId=',ep.id,'&processId=',ep.process_id) flow_url , CONCAT(#{goodsOutBpmUrlPre},'&formInstanceId=',gp.id,'&processId=',gp.flow_id) goods_out_flow_url from safety_goods_out_events_process ep inner join safety_goods_out_process gp on ep.related_process_id = gp.id
) as cur where event_type is not null
and plan_type = #{planType}
and plan_name like CONCAT('%',#{planName},'%')
order by create_time desc
limit ${offset}, ${limit}
limit ${limit}

select count(1) from(SELECT sp.id,sp.flow_id,sp.flow_no,sp.factory_id,sp.factory,sp.event_source,sp.event_id,M1.field_name event_type,sp.task_id, sp.team_id,M2.field_name team_name,case sp.event_source when 2 then '事件上报' else sp.plan_name end plan_name, sp.is_exception,sp.event_level,sp.duty_dept,sp.occur_time,sp.event_address,sp.is_keynote,sp.problem_desc, sp.problem_image,sp.plan_deal_time,sp.plan_measure,sp.is_scene,sp.is_transfer,sp.transfer_dept,sp.deal_person,sp.deal_person_group, sp.guard_person,sp.deal_time,sp.deal_record,sp.deal_image,sp.result_score,sp.result_desc,sp.result_person, sp.is_delay,sp.submit_name,sp.submit_dept,sp.grab_person,sp.grab_time,DATE_FORMAT(sp.create_time,'%Y-%m-%d %H:%i:%s') create_time, sp.is_grab,sp.is_dispatch,sp.dispatch_person,IFNULL(dh.rework_num,0) rework_num,sp.status,sp.is_deal_transfer,sp.cur_deal_handler, '' car_number,'' telephone,'' driver_name,1 plan_type,'' as is_assign FROM safety_process_patrol sp LEFT JOIN (select pd.process_id,count(1) rework_num from safety_patrol_deal_history pd group by pd.process_id) dh on sp.id = dh.process_id LEFT JOIN SAFETY.safety_field_manage M1 ON sp.event_id = M1.ID LEFT JOIN SAFETY.safety_field_manage M2 ON sp.team_id = M2.ID WHERE 1 = 1
union all SELECT sv.id,'' flow_id,sv.flow_no,sv.factory_id,sv.factory,sv.event_source,sv.event_id,M3.field_name event_type,sv.task_id, sv.team_id,M4.field_name team_name,sv.plan_name,0 is_exception,'' event_level,'' duty_dept,'' occur_time,'' event_address, 0 is_keynote,'' problem_desc,'' problem_image, '' plan_deal_time,'' plan_measure,0 is_scene,0 is_transfer, '' transfer_dept,sv.check_person deal_person,sv.check_dept deal_person_group,'' guard_person,sv.check_time deal_time,'' deal_record,'' deal_image,'' result_score,'' result_desc,'' result_person, 0 is_delay, sv.check_person submit_name,sv.check_dept submit_dept,'' grab_person,'' grab_time,DATE_FORMAT(sv.create_time,'%Y-%m-%d %H:%i:%s') create_time,0 is_grab,0 is_dispatch,'' dispatch_person,0 rework_num,'' status,0, '' cur_deal_handler, sv.car_number,sv.telephone,sv.driver_name,2 plan_type,'' as is_assign FROM safety_validate_environment sv LEFT JOIN SAFETY.safety_field_manage M3 ON sv.event_id = M3.ID LEFT JOIN SAFETY.safety_field_manage M4 ON sv.team_id = M4.ID where 1 = 1
union all select ep.id, ep.process_id as flow_id, ep.process_id as flow_no, ep.site_id as factory_id, ep.site_name as factory, '' as event_source, '' as event_id, ep.event_type , '' as task_id, '' as team_id, ep.issue_type as team_name, '出门证违规上报' as plan_name, '' as is_exception, ep.event_level , ep.responsible_person_department as duty_dept, ep.event_occurrence_time as occur_time, ep.specific_location as event_address, '' as is_keynote, ep.issue_description as problem_desc, '' problem_image, '' plan_deal_time, '' plan_measure, '' is_scene, '' is_transfer, '' transfer_dept, ep.remediation_name as deal_person, '' deal_person_group, '' guard_person, ep.remediation_completion_time as deal_time, ep.remediation_measure as deal_record, '' deal_image, '' result_score, '' result_desc, '' result_person, '' is_delay, ep.reporter_name as submit_name, '' submit_dept, '' grab_person, '' grab_time, ep.creation_time as create_time, '' is_grab, '' is_dispatch, '' dispatch_person, '' rework_num, '' status, '' is_deal_transfer, '' cur_deal_handler, '' car_number, '' telephone, '' driver_name, 1 plan_type, 0 as is_assign from safety_goods_out_events_process ep
) as cur where event_type is not null
and plan_type = #{planType}
and plan_name like CONCAT('%',#{planName},'%')

mapper.update:
update safety_process_patrol
   set cur_deal_handler = #{curDealHandler}
 where id = #{id}

update safety_process_patrol
   set flow_id = #{flowId}
 where id = #{id}

update.foreach:
update safety_process_patrol
set cur_deal_handler = #{item.fdCurrLoginNames},
cur_node_id=#{item.nodeIds},
status = #{item.fdStatus}
where flow_id = #{item.modelId}
